excels.excel:

EXPORT WITH SHEET="客户分层报表", HEADER=true,
    MAPPING={"a":"客户编码","b":"客户名称","c":"客户等级","d":"年度成交额","e":"贡献占比"},
    FORMAT={"d":"#,##0.00","e":"0.00%"},
    FORMULAS={
        E2:'D2/SUM(D2:D6)',E3:'D3/SUM(D2:D6)',E4:'D4/SUM(D2:D6)',
        E5:'D5/SUM(D2:D6)',E6:'D6/SUM(D2:D6)',
        D7:'SUM(D2:D6)',E7:'SUM(E2:E6)'
    },
    STYLE={ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}}
